// Get the webhook data from input
const webhookData = input.webhookNJLB?.[0];

// The webhook body is an array of multiple events (property changes, associations, creation, etc.)
// We need to scan ALL items to find the objectId and check if ANY event was user-initiated
const bodyItems = webhookData?.body || [];

// Extract objectId from the first item that has one (objectId for property changes, fromObjectId for associations)
const objectId = bodyItems.reduce((id, item) => {
  if (id) return id;
  return item?.objectId || item?.fromObjectId || null;
}, null);

// Loop prevention: check if ANY event in the batch has a userId sourceId
// Some events (like association changes) don't have sourceId at all, but the
// accompanying property change events do. If at least one is user-initiated, it's legit.
const isUserChange = bodyItems.some(item => {
  const sid = item?.sourceId || '';
  return String(sid).startsWith('userId:');
});

// Create the filterGroups array with the required structure
// Convert objectId to string as HubSpot expects string values
return {
  filterGroups:[{
    filters: [{
      propertyName: "hs_object_id",
      operator: "EQ",
      value: String(objectId)
    }]
  }],
  dealId: String(objectId),
  isUserChange: isUserChange
};

const dealId = input.mapNABN?.[0]?.dealId || input.mapNABN?.dealId || '';
const lockKey = 'hubspot_deal_' + dealId + '_acumatica_sync';
return [{ lockKey, dealId }];

// Get the lock key from the Build Lock Key step
const lockKey = input.mapFGWE?.[0]?.lockKey || '';

// Get the lockedKeys directly from memory
const memoryValue = input.memory?.lockedKeys;

// Parse the memory value as a JSON array, defaulting to empty array
let lockedKeys = [];
try {
  const parsed = typeof memoryValue === 'string' ? JSON.parse(memoryValue) : memoryValue;
  if (Array.isArray(parsed)) lockedKeys = parsed;
} catch (e) {
  lockedKeys = [];
}

// Check if the lockKey already exists in the locked keys array
const isLocked = lockedKeys.includes(lockKey);

return [{ isLocked, lockKey, lockedKeys }];

// Get the lock key and current lockedKeys from Check if Lock Exists step
const lockKey = input.mapGQXB?.[0]?.lockKey || '';
const lockedKeys = input.mapGQXB?.[0]?.lockedKeys || [];

// Add the new lock key to the array
const updatedLockedKeys = [...lockedKeys, lockKey];

return [{ updatedLockedKeys: JSON.stringify(updatedLockedKeys) }];

const associations = input.hubspotAppGetAssociationsH7I7;

// Map each association to a filter object
return associations.map((association) => ({
  filters: [
    {
      propertyName: "hs_object_id",
      operator: "EQ",
      value: String(association?.toObjectId)
    }
  ]
}));

