// Helper function to convert epoch milliseconds to date string
function fromEpochMs(epochMs) {
  if (!epochMs) return '';
  const date = new Date(epochMs);
  if (isNaN(date.getTime())) return '';
  return date.toISOString();
}

// Get HubSpot owner ID and map to Acumatica owner name
const hubspotOwnerId = deal?.properties?.hubspotOwnerId || '';
const acumaticaOwner = hubspotOwnerToAcumatica[hubspotOwnerId] || '';

// Get HubSpot stage ID and map to Acumatica stage name
const hubspotStageId = deal?.properties?.dealstage || '';
const acumaticaStage = hubspotStageToAcumatica[hubspotStageId] || '';

// Convert closedate from epoch ms to date string
const closeDateEpoch = deal?.properties?.closedate || '';
const closeDateFormatted = fromEpochMs(closeDateEpoch);

// Build the Acumatica-formatted object
const acumaticaOpportunity = {
  Subject: { value: deal?.properties?.dealname || '' },
  BusinessAccount: { value: company?.properties?.acumaticaCustomerId || '' },
  Contact: { value: contact?.properties?.acumaticaContactId || '' },
  Owner: { value: acumaticaOwner },
  Stage: { value: acumaticaStage },
  CuryAmount: { value: deal?.properties?.amount || '' },
  Estimation: { value: closeDateFormatted },
  custom: {
    Opportunity: {
      UsrHSDealID: { value: deal.id }
    }
  },
};

return [acumaticaOpportunity];

