// Step 24 - Create/Update Contact in Acumatica (existing customer path)
const acumaticaContact = input.acumaticaNewAction19XF1?.[0];
// Step 19 - Map HubSpot Deal to Acumatica Opportunity (fallback)
const opportunityMap = input.mapJIFP?.[0];

// Use step 19's Contact value first, if empty fall back to step 24's contactID
const contactId = opportunityMap?.Contact?.value || acumaticaContact?.contactID?.value?.toString() || '';

