}];

const companies = input.hubspotAppSearchCompaniesWTEV;
const contacts = input.hubspotAppSearchContactsQK2A;

// Get the first company from the search results
const company = companies?.[0];
const props = company?.properties || {};

// Find the first contact with a non-empty email
const contactFound = contacts?.[0];
const email = contactFound?.properties?.email || "";
const contactProps = contactFound?.properties || {};
const firstName = contactProps.firstname || "";
const lastName = contactProps.lastname || "";
const phone = contactProps.phone || "";
const jobTitle = contactProps.jobtitle || "";
const contactId = contactFound.id

// Build Address object with only non-empty fields
const address = {
  ...(props.address ? { AddressLine1: { value: props.address } } : {}),
  ...(props.city ? { City: { value: props.city } } : {}),
  ...(props.state ? { State: { value: props.state } } : {}),
  ...(props.zip ? { PostalCode: { value: props.zip } } : {}),
  ...(props.country ? { Country: { value: props.country } } : {})
};

// Build MainContact with only non-empty fields
const mainContact = {
  ...(email ? { Email: { value: email } } : {}),
  ...(props.phone ? { Phone1: { value: props.phone } } : {}),
  ...(Object.keys(address).length > 0 ? { Address: address } : {}),
  ...(props.website ? { Website: { value: props.website } } : {})
};

// Map HubSpot company properties to Acumatica Customer fields
return [{
  CustomerName: { value: props.name || "" },
  ...(Object.keys(mainContact).length > 0 ? { MainContact: mainContact } : {}),
  AcumaticaCustomerID: { value: props.acumatica_customer_id || "" },
  custom: {
    Customer: {
      UsrHSCompanyID: {
        value: company.id
      }
    }
  },
  Contact: {
    FirstName: { value: firstName },
    LastName:  { value: lastName },
    Email: { value: email },
    Phone: { value: phone },
    JobTitle: { value: jobTitle },
    custom: {
      Contact: {
        UsrHSContactID: {
          value: contactId
        }
      }

    }
  }
}];

// Get the lock key from the Build Lock Key step
const lockKey = input.mapFGWE?.[0]?.lockKey || '';

// Get the current lockedKeys from memory
const memoryValue = input.memory?.lockedKeys;

let lockedKeys = [];
try {
  const parsed = typeof memoryValue === 'string' ? JSON.parse(memoryValue) : memoryValue;
  if (Array.isArray(parsed)) lockedKeys = parsed;
} catch (e) {
  lockedKeys = [];
}

// Remove the current deal's lock key
const updatedLockedKeys = lockedKeys.filter(key => key !== lockKey);

return [{ updatedLockedKeys: JSON.stringify(updatedLockedKeys) }];
